/// <summary>
/// CB201 - Rebate aggregation value parameter
/// </summary>
/// <param name = "_aggregatedStr">Aggregatore value</param>
/// <returns>Aggregatore value</returns>
public str parmCurrentAggregatedStr(str _aggregatedStr = currentAggregatedStr)
{
    currentAggregatedStr = _aggregatedStr;
    return currentAggregatedStr;
}
